Superset of JavaScript adding static typing, compiled to JavaScript.

```typescript
let age: number = 25;
let name: string = "John";
```

`number`, `string`, `boolean`, `any`, `unknown`, `void`, `null`, `undefined`, `never`, `object`.

```typescript
let num: number = 42;
let str: string = "hello";
let bool: boolean = true;
let anything: any = "can be anything";
```

Explicit type declaration.

```typescript
let name: string = "John";
function greet(name: string): string {
  return `Hello, ${name}`;
}
```

Defines structure of an object.

```typescript
interface User {
  id: number;
  name: string;
  email?: string; // optional
}

const user: User = { id: 1, name: "John" };
```

Creates new name for a type.

```typescript
type UserID = string | number;
type Point = { x: number; y: number };

let id: UserID = 123;
```

- Interface: can be extended, merged, better for objects
- Type: more flexible, can represent unions, primitives

```typescript
// Interface
interface Animal { name: string; }
interface Dog extends Animal { breed: string; }

// Type
type Animal = { name: string };
type Dog = Animal & { breed: string };
```

Combines multiple types.

```typescript
type Person = { name: string };
type Employee = { employeeId: number };
type Staff = Person & Employee;

const staff: Staff = { name: "John", employeeId: 123 };
```

Represents absence of value (function returns nothing).

```typescript
function log(message: string): void {
  console.log(message);
}
```

Represents values that never occur (functions that never return).

```typescript
function throwError(message: string): never {
  throw new Error(message);
}

function infiniteLoop(): never {
  while (true) {}
}
```

Telling compiler to treat value as specific type.

```typescript
let value: any = "hello";
let length: number = (value as string).length;
// or
let length2: number = (<string>value).length;
```

Named set of constants.

```typescript
enum Color {
  Red,
  Green,
  Blue
}

let c: Color = Color.Green; // 1

enum Status {
  Active = "ACTIVE",
  Inactive = "INACTIVE"
}
```

Reusable component working with multiple types.

```typescript
function identity<T>(arg: T): T {
  return arg;
}

identity<number>(5);
identity<string>("hello");
```

Limiting generic types.

```typescript
interface HasLength {
  length: number;
}

function logLength<T extends HasLength>(arg: T): void {
  console.log(arg.length);
}

logLength("hello"); // OK
logLength([1, 2, 3]); // OK
logLength(123); // Error
```

Gets union of object's keys.

```typescript
interface User {
  id: number;
  name: string;
}

type UserKeys = keyof User; // "id" | "name"

function getProperty<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}
```

Gets type of a variable.

```typescript
let user = { name: "John", age: 25 };
type User = typeof user; // { name: string; age: number }
```

Dynamic property names.

```typescript
interface StringMap {
  [key: string]: string;
}

const map: StringMap = {
  name: "John",
  city: "NYC"
};
```

Transforms properties of existing type.

```typescript
type Readonly<T> = {
  readonly [P in keyof T]: T[P];
};

interface User {
  name: string;
  age: number;
}

type ReadonlyUser = Readonly<User>;
```

Makes all properties optional.

```typescript
interface User {
  name: string;
  age: number;
}

type PartialUser = Partial<User>;
// { name?: string; age?: number; }

function updateUser(user: User, updates: Partial<User>) {
  return { ...user, ...updates };
}
```

Makes all properties required.

```typescript
interface User {
  name?: string;
  age?: number;
}

type RequiredUser = Required<User>;
// { name: string; age: number; }
```

Selects subset of properties.

```typescript
interface User {
  id: number;
  name: string;
  email: string;
}

type UserPreview = Pick<User, "id" | "name">;
// { id: number; name: string; }
```

Excludes properties.

```typescript
interface User {
  id: number;
  name: string;
  password: string;
}

type PublicUser = Omit<User, "password">;
// { id: number; name: string; }
```

Creates object type with specific keys and value type.

```typescript
type Roles = "admin" | "user" | "guest";
type Permissions = Record<Roles, string[]>;

const perms: Permissions = {
  admin: ["read", "write", "delete"],
  user: ["read", "write"],
  guest: ["read"]
};
```

Makes all properties read-only.

```typescript
interface User {
  name: string;
  age: number;
}

const user: Readonly<User> = { name: "John", age: 25 };
user.name = "Jane"; // Error
```

Type definition for functions.

```typescript
type MathOperation = (a: number, b: number) => number;

const add: MathOperation = (a, b) => a + b;
const subtract: MathOperation = (a, b) => a - b;
```

Parameters that may be omitted.

```typescript
function greet(name: string, greeting?: string): string {
  return `${greeting || "Hello"}, ${name}`;
}

greet("John"); // "Hello, John"
greet("John", "Hi"); // "Hi, John"
```

Parameters with default values.

```typescript
function greet(name: string, greeting: string = "Hello"): string {
  return `${greeting}, ${name}`;
}
```

Array of remaining arguments.

```typescript
function sum(...numbers: number[]): number {
  return numbers.reduce((a, b) => a + b, 0);
}

sum(1, 2, 3, 4);
```

Multiple function signatures.

```typescript
function getValue(id: number): string;
function getValue(name: string): number;
function getValue(value: number | string): string | number {
  if (typeof value === "number") return "id: " + value;
  return value.length;
}
```

Blueprint for creating objects with type safety.

```typescript
class Person {
  name: string;
  age: number;

  constructor(name: string, age: number) {
    this.name = name;
    this.age = age;
  }

  greet(): string {
    return `Hello, ${this.name}`;
  }
}
```

`public`, `private`, `protected` control property/method access.

```typescript
class Person {
  public name: string; // accessible everywhere
  private ssn: string; // only within class
  protected age: number; // within class and subclasses

  constructor(name: string, ssn: string, age: number) {
    this.name = name;
    this.ssn = ssn;
    this.age = age;
  }
}
```

Properties that cannot be modified after initialization.

```typescript
class Person {
  readonly id: number;

  constructor(id: number) {
    this.id = id;
  }
}

const person = new Person(1);
person.id = 2; // Error
```

Base class that cannot be instantiated.

```typescript
abstract class Animal {
  abstract makeSound(): void;

  move(): void {
    console.log("moving");
  }
}

class Dog extends Animal {
  makeSound(): void {
    console.log("bark");
  }
}
```

Runtime check that narrows type.

```typescript
function isString(value: unknown): value is string {
  return typeof value === "string";
}

function process(value: string | number) {
  if (isString(value)) {
    console.log(value.toUpperCase()); // string
  } else {
    console.log(value.toFixed(2)); // number
  }
}
```

Checks if property exists.

```typescript
interface Cat { meow(): void; }
interface Dog { bark(): void; }

function makeSound(animal: Cat | Dog) {
  if ("meow" in animal) {
    animal.meow();
  } else {
    animal.bark();
  }
}
```

Checks if object is instance of class.

```typescript
class Dog {
  bark() { console.log("woof"); }
}

function handle(animal: Dog | Cat) {
  if (animal instanceof Dog) {
    animal.bark();
  }
}
```

Union with common property for type narrowing.

```typescript
interface Success {
  type: "success";
  data: string;
}

interface Error {
  type: "error";
  message: string;
}

type Result = Success | Error;

function handle(result: Result) {
  if (result.type === "success") {
    console.log(result.data); // Success type
  } else {
    console.log(result.message); // Error type
  }
}
```

Organize code into logical groups.

```typescript
namespace Utils {
  export function log(msg: string) {
    console.log(msg);
  }
}

Utils.log("hello");
```

File with imports/exports.

```typescript
// math.ts
export function add(a: number, b: number): number {
  return a + b;
}

// app.ts
import { add } from './math';
```

Function that modifies class/method/property.

```typescript
function log(target: any, key: string) {
  console.log(`${key} was called`);
}

class Calculator {
  @log
  add(a: number, b: number) {
    return a + b;
  }
}
```

Enables all strict type checking options.

```json
{
  "compilerOptions": {
    "strict": true
  }
}
```

Tells compiler value is not null/undefined.

```typescript
function process(value?: string) {
  console.log(value!.length); // asserts value is not null/undefined
}
```

Safely access nested properties.

```typescript
interface User {
  address?: {
    city?: string;
  };
}

const user: User = {};
const city = user.address?.city; // undefined (no error)
```

Default value for null/undefined.

```typescript
const value: string | null = null;
const result = value ?? "default"; // "default"

const zero = 0 ?? 42; // 0 (not 42)
```
